import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int d = in.nextInt();
        int p = in.nextInt();
        System.out.println((d + p - 1) / p);
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int d, p;
    cin >> d >> p;
    cout << (d + p - 1) / p << endl;
    return 0;
}
